commit 7c75b166c8bd767a78ad55dbd16dadf1e026a1c7
Author: Werner Lemberg <wl@gnu.org>
Date:   Sat Dec 17 13:28:24 2016 +0100

    [sfnt, truetype] Various sanitizing fixes.

    * src/sfnt/sfobjs.c (sfnt_init_face): If the axis count in `fvar' is
    zero, set `num_instances' to zero.

    * src/truetype/ttgxvar.c (TT_Get_MM_Var): Handle `fvar' table with
    zero axes as invalid.

    * src/truetype/ttobjs.c (tt_face_init): Improve logic of loading
    `loca', `cvt', `fpgm', and `prep' table.

diff --git a/src/truetype/ttgxvar.c b/src/truetype/ttgxvar.c
index 12a316036..8746b25f5 100644
--- a/src/truetype/ttgxvar.c
+++ b/src/truetype/ttgxvar.c
@@ -1268,180 +1268,181 @@
   {
     FT_Stream            stream = face->root.stream;
     FT_Memory            memory = face->root.memory;
     FT_ULong             table_len;
     FT_Error             error  = FT_Err_Ok;
     FT_ULong             fvar_start;
     FT_Int               i, j;
     FT_MM_Var*           mmvar = NULL;
     FT_Fixed*            next_coords;
     FT_String*           next_name;
     FT_Var_Axis*         a;
     FT_Var_Named_Style*  ns;
     GX_FVar_Head         fvar_head;
     FT_Bool              usePsName;

     static const FT_Frame_Field  fvar_fields[] =
     {

 #undef  FT_STRUCTURE
 #define FT_STRUCTURE  GX_FVar_Head

       FT_FRAME_START( 16 ),
         FT_FRAME_LONG  ( version ),
         FT_FRAME_USHORT( offsetToData ),
         FT_FRAME_USHORT( countSizePairs ),
         FT_FRAME_USHORT( axisCount ),
         FT_FRAME_USHORT( axisSize ),
         FT_FRAME_USHORT( instanceCount ),
         FT_FRAME_USHORT( instanceSize ),
       FT_FRAME_END
     };

     static const FT_Frame_Field  fvaraxis_fields[] =
     {

 #undef  FT_STRUCTURE
 #define FT_STRUCTURE  GX_FVar_Axis

       FT_FRAME_START( 20 ),
         FT_FRAME_ULONG ( axisTag ),
         FT_FRAME_LONG  ( minValue ),
         FT_FRAME_LONG  ( defaultValue ),
         FT_FRAME_LONG  ( maxValue ),
         FT_FRAME_USHORT( flags ),
         FT_FRAME_USHORT( nameID ),
       FT_FRAME_END
     };


     /* read the font data and set up the internal representation */
     /* if not already done                                       */

     if ( face->blend == NULL )
     {
       FT_TRACE2(( "FVAR " ));

       /* both `fvar' and `gvar' must be present */
       if ( ( error = face->goto_table( face, TTAG_gvar,
                                        stream, &table_len ) ) != 0 )
       {
         /* CFF2 is an alternate to gvar here */
         if ( ( error = face->goto_table( face, TTAG_CFF2,
                                          stream, &table_len ) ) != 0 )
         {
           FT_TRACE1(( "\n"
                       "TT_Get_MM_Var: `gvar' or `CFF2' table is missing\n" ));
           goto Exit;
         }
       }

       if ( ( error = face->goto_table( face, TTAG_fvar,
                                        stream, &table_len ) ) != 0 )
       {
         FT_TRACE1(( "is missing\n" ));
         goto Exit;
       }

       fvar_start = FT_STREAM_POS( );

       if ( FT_STREAM_READ_FIELDS( fvar_fields, &fvar_head ) )
         goto Exit;

       if ( fvar_head.version != (FT_Long)0x00010000L                      ||
 #if 0
            /* fonts like `JamRegular.ttf' have an incorrect value for */
            /* `countSizePairs'; since value 2 is hard-coded in `fvar' */
            /* version 1.0, we simply ignore it                        */
            fvar_head.countSizePairs != 2                                  ||
 #endif
            fvar_head.axisSize != 20                                       ||
+           fvar_head.axisCount == 0                                       ||
            /* axisCount limit implied by 16-bit instanceSize */
            fvar_head.axisCount > 0x3FFE                                   ||
            fvar_head.instanceCount > 0x7EFF                               ||
            fvar_head.offsetToData + fvar_head.axisCount * 20U +
              fvar_head.instanceCount * fvar_head.instanceSize > table_len )
       {
         FT_TRACE1(( "\n"
                     "TT_Get_MM_Var: invalid `fvar' header\n" ));
         error = FT_THROW( Invalid_Table );
         goto Exit;
       }

       if ( fvar_head.instanceSize == 4 + 4 * fvar_head.axisCount )
         usePsName = FALSE;
       else if ( fvar_head.instanceSize == 6 + 4 * fvar_head.axisCount )
         usePsName = TRUE;
       else
       {
         FT_TRACE1(( "\n"
                     "TT_Get_MM_Var: invalid `fvar' header\n" ));
         error = FT_THROW( Invalid_Table );
         goto Exit;
       }

       FT_TRACE2(( "loaded\n" ));

       FT_TRACE5(( "number of GX style axes: %d\n", fvar_head.axisCount ));

       if ( FT_NEW( face->blend ) )
         goto Exit;

       /* cannot overflow 32-bit arithmetic because of limits above */
       face->blend->mmvar_len =
         sizeof ( FT_MM_Var ) +
         fvar_head.axisCount * sizeof ( FT_Var_Axis ) +
         fvar_head.instanceCount * sizeof ( FT_Var_Named_Style ) +
         fvar_head.instanceCount * fvar_head.axisCount * sizeof ( FT_Fixed ) +
         5 * fvar_head.axisCount;

       if ( FT_ALLOC( mmvar, face->blend->mmvar_len ) )
         goto Exit;
       face->blend->mmvar = mmvar;

       /* set up pointers and offsets into the `mmvar' array; */
       /* the data gets filled in later on                    */

       mmvar->num_axis =
         fvar_head.axisCount;
       mmvar->num_designs =
         ~0U;                   /* meaningless in this context; each glyph */
                                /* may have a different number of designs  */
                                /* (or tuples, as called by Apple)         */
       mmvar->num_namedstyles =
         fvar_head.instanceCount;
       mmvar->axis =
         (FT_Var_Axis*)&( mmvar[1] );
       mmvar->namedstyle =
         (FT_Var_Named_Style*)&( mmvar->axis[fvar_head.axisCount] );

       next_coords =
         (FT_Fixed*)&( mmvar->namedstyle[fvar_head.instanceCount] );
       for ( i = 0; i < fvar_head.instanceCount; i++ )
       {
         mmvar->namedstyle[i].coords  = next_coords;
         next_coords                 += fvar_head.axisCount;
       }

       next_name = (FT_String*)next_coords;
       for ( i = 0; i < fvar_head.axisCount; i++ )
       {
         mmvar->axis[i].name  = next_name;
         next_name           += 5;
       }

       /* now fill in the data */

       if ( FT_STREAM_SEEK( fvar_start + fvar_head.offsetToData ) )
         goto Exit;

       a = mmvar->axis;
       for ( i = 0; i < fvar_head.axisCount; i++ )
       {
         GX_FVar_Axis  axis_rec;


         if ( FT_STREAM_READ_FIELDS( fvaraxis_fields, &axis_rec ) )
           goto Exit;
         a->tag     = axis_rec.axisTag;
         a->minimum = axis_rec.minValue;
         a->def     = axis_rec.defaultValue;
diff --git a/src/truetype/ttobjs.c b/src/truetype/ttobjs.c
index 758eaeb44..81577a49b 100644
--- a/src/truetype/ttobjs.c
+++ b/src/truetype/ttobjs.c
@@ -494,212 +494,241 @@
   /*    face_index :: The index of the TrueType font, if we are opening a  */
   /*                  collection, in bits 0-15.  The numbered instance     */
   /*                  index~+~1 of a GX (sub)font, if applicable, in bits  */
   /*                  16-30.                                               */
   /*                                                                       */
   /*    num_params :: Number of additional generic parameters.  Ignored.   */
   /*                                                                       */
   /*    params     :: Additional generic parameters.  Ignored.             */
   /*                                                                       */
   /* <InOut>                                                               */
   /*    face       :: The newly built face object.                         */
   /*                                                                       */
   /* <Return>                                                              */
   /*    FreeType error code.  0 means success.                             */
   /*                                                                       */
   FT_LOCAL_DEF( FT_Error )
   tt_face_init( FT_Stream      stream,
                 FT_Face        ttface,      /* TT_Face */
                 FT_Int         face_index,
                 FT_Int         num_params,
                 FT_Parameter*  params )
   {
     FT_Error      error;
     FT_Library    library;
     SFNT_Service  sfnt;
     TT_Face       face = (TT_Face)ttface;


     FT_TRACE2(( "TTF driver\n" ));

     library = ttface->driver->root.library;

     sfnt = (SFNT_Service)FT_Get_Module_Interface( library, "sfnt" );
     if ( !sfnt )
     {
       FT_ERROR(( "tt_face_init: cannot access `sfnt' module\n" ));
       error = FT_THROW( Missing_Module );
       goto Exit;
     }

     /* create input stream from resource */
     if ( FT_STREAM_SEEK( 0 ) )
       goto Exit;

     /* check that we have a valid TrueType file */
     error = sfnt->init_face( stream, face, face_index, num_params, params );

     /* Stream may have changed. */
     stream = face->root.stream;

     if ( error )
       goto Exit;

     /* We must also be able to accept Mac/GX fonts, as well as OT ones. */
     /* The 0x00020000 tag is completely undocumented; some fonts from   */
     /* Arphic made for Chinese Windows 3.1 have this.                   */
     if ( face->format_tag != 0x00010000L &&    /* MS fonts  */
          face->format_tag != 0x00020000L &&    /* CJK fonts for Win 3.1 */
          face->format_tag != TTAG_true   )     /* Mac fonts */
     {
       FT_TRACE2(( "  not a TTF font\n" ));
       goto Bad_Format;
     }

 #ifdef TT_USE_BYTECODE_INTERPRETER
     ttface->face_flags |= FT_FACE_FLAG_HINTER;
 #endif

     /* If we are performing a simple font format check, exit immediately. */
     if ( face_index < 0 )
       return FT_Err_Ok;

     /* Load font directory */
     error = sfnt->load_face( stream, face, face_index, num_params, params );
     if ( error )
       goto Exit;

     if ( tt_check_trickyness( ttface ) )
       ttface->face_flags |= FT_FACE_FLAG_TRICKY;

     error = tt_face_load_hdmx( face, stream );
     if ( error )
       goto Exit;

     if ( FT_IS_SCALABLE( ttface ) )
     {

 #ifdef FT_CONFIG_OPTION_INCREMENTAL

       if ( !ttface->internal->incremental_interface )
+      {
         error = tt_face_load_loca( face, stream );
-      if ( !error )
-        error = tt_face_load_cvt( face, stream );
-      if ( !error )
-        error = tt_face_load_fpgm( face, stream );
-      if ( !error )
-        error = tt_face_load_prep( face, stream );
+
+        /* having a (non-zero) `glyf' table without */
+        /* a `loca' table is not valid              */
+        if ( face->glyf_len && FT_ERR_EQ( error, Table_Missing ) )
+          goto Exit;
+        if ( error )
+          goto Exit;
+      }
+
+      /* `fpgm', `cvt', and `prep' are optional */
+      error = tt_face_load_cvt( face, stream );
+      if ( error && FT_ERR_NEQ( error, Table_Missing ) )
+        goto Exit;
+
+      error = tt_face_load_fpgm( face, stream );
+      if ( error && FT_ERR_NEQ( error, Table_Missing ) )
+        goto Exit;
+
+      error = tt_face_load_prep( face, stream );
+      if ( error && FT_ERR_NEQ( error, Table_Missing ) )
+        goto Exit;

       /* Check the scalable flag based on `loca'. */
       if ( !ttface->internal->incremental_interface &&
            ttface->num_fixed_sizes                  &&
            face->glyph_locations                    &&
            tt_check_single_notdef( ttface )         )
       {
         FT_TRACE5(( "tt_face_init:"
                     " Only the `.notdef' glyph has an outline.\n"
                     "             "
                     " Resetting scalable flag to FALSE.\n" ));

         ttface->face_flags &= ~FT_FACE_FLAG_SCALABLE;
       }

 #else /* !FT_CONFIG_OPTION_INCREMENTAL */

-      if ( !error )
-        error = tt_face_load_loca( face, stream );
-      if ( !error )
-        error = tt_face_load_cvt( face, stream );
-      if ( !error )
-        error = tt_face_load_fpgm( face, stream );
-      if ( !error )
-        error = tt_face_load_prep( face, stream );
+      error = tt_face_load_loca( face, stream );
+
+      /* having a (non-zero) `glyf' table without */
+      /* a `loca' table is not valid              */
+      if ( face->glyf_len && FT_ERR_EQ( error, Table_Missing ) )
+        goto Exit;
+      if ( error )
+        goto Exit;
+
+      /* `fpgm', `cvt', and `prep' are optional */
+      error = tt_face_load_cvt( face, stream );
+      if ( error && FT_ERR_NEQ( error, Table_Missing ) )
+        goto Exit;
+
+      error = tt_face_load_fpgm( face, stream );
+      if ( error && FT_ERR_NEQ( error, Table_Missing ) )
+        goto Exit;
+
+      error = tt_face_load_prep( face, stream );
+      if ( error && FT_ERR_NEQ( error, Table_Missing ) )
+        goto Exit;

       /* Check the scalable flag based on `loca'. */
       if ( ttface->num_fixed_sizes          &&
            face->glyph_locations            &&
            tt_check_single_notdef( ttface ) )
       {
         FT_TRACE5(( "tt_face_init:"
                     " Only the `.notdef' glyph has an outline.\n"
                     "             "
                     " Resetting scalable flag to FALSE.\n" ));

         ttface->face_flags &= ~FT_FACE_FLAG_SCALABLE;
       }

 #endif /* !FT_CONFIG_OPTION_INCREMENTAL */

     }

 #ifdef TT_CONFIG_OPTION_GX_VAR_SUPPORT

     {
       FT_Int  instance_index = face_index >> 16;


       if ( FT_HAS_MULTIPLE_MASTERS( ttface ) &&
            instance_index > 0                )
       {
         error = TT_Get_MM_Var( face, NULL );
         if ( error )
           goto Exit;

         if ( face->blend->mmvar->namedstyle )
         {
           FT_Memory  memory = ttface->memory;

           FT_Var_Named_Style*  named_style;
           FT_String*           style_name;


           /* in `face_index', the instance index starts with value 1 */
           named_style = face->blend->mmvar->namedstyle + instance_index - 1;
           error = sfnt->get_name( face,
                                   (FT_UShort)named_style->strid,
                                   &style_name );
           if ( error )
             goto Exit;

           /* set style name; if already set, replace it */
           if ( face->root.style_name )
